-- 601: Original BrillaPrep Cambridge IGCSE Chemistry (0620) sprint 3 beta questions, part 8 of 13 (batch igcse-chemistry-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_601_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_601_guard;
INSERT INTO _migration_601_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_029' AND NOT (q.topic_id IS 'topic_igcse_chem_metals' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In the blast furnace, iron is extracted from iron(III) oxide. Which substance reduces the iron(III) oxide to iron?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Carbon monoxide","B. Oxygen","C. Nitrogen","D. Calcium carbonate"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Carbon monoxide, formed from the burning coke, is the reducing agent: Fe₂O₃ + 3CO → 2Fe + 3CO₂. (Oxygen would oxidise, not reduce; nitrogen is inert here; calcium carbonate removes sandy impurities as slag but does not reduce the ore.) Therefore the correct answer is A: Carbon monoxide.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_029' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_601_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_030' AND NOT (q.topic_id IS 'topic_igcse_chem_metals' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A student investigates the reactivity of magnesium, zinc, iron and copper by adding a small piece of each metal to separate samples of dilute hydrochloric acid.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) rapid effervescence as the magnesium dissolves; (b) Zn + 2HCl → ZnCl₂ + H₂; (c) magnesium, zinc, iron, copper.' AND q.explanation IS '(a) Magnesium is high in the reactivity series, so it reacts vigorously with the acid, giving bubbles of hydrogen and heat. (b) Zinc forms zinc chloride and hydrogen: Zn(s) + 2HCl(aq) → ZnCl₂(aq) + H₂(g); the 2 balances the chlorine and hydrogen atoms. (c) Vigour of reaction gives magnesium > zinc > iron, and copper, which shows no reaction, is the least reactive of the four.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '4' AND q.time_limit IS '300' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Describe' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_030' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_601_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_031' AND NOT (q.topic_id IS 'topic_igcse_chem_organic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the general formula of the alkenes?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. CₙH₂ₙ₊₂","B. CₙH₂ₙ","C. CₙH₂ₙ₋₂","D. CₙH₂ₙ₊₁OH"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Alkenes contain one C=C double bond, so they have two fewer hydrogen atoms than the corresponding alkane: CₙH₂ₙ. (CₙH₂ₙ₊₂ is the alkane series; CₙH₂ₙ₋₂ would have two degrees of unsaturation; CₙH₂ₙ₊₁OH describes an alcohol.) Therefore the correct answer is B: CₙH₂ₙ.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_031' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_601_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_032' AND NOT (q.topic_id IS 'topic_igcse_chem_organic' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which functional group is present in every molecule of ethanol?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The carboxyl group, –COOH","B. The carbon-to-carbon double bond, C=C","C. The hydroxyl group, –OH","D. The ester linkage, –COO–"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Ethanol, C₂H₅OH, is an alcohol, and the alcohol functional group is the hydroxyl group –OH. (–COOH is found in carboxylic acids such as ethanoic acid; C=C is found in alkenes; –COO– is found in esters.) Therefore the correct answer is C: The hydroxyl group, –OH.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_032' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_029', 'topic_igcse_chem_metals', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'In the blast furnace, iron is extracted from iron(III) oxide. Which substance reduces the iron(III) oxide to iron?', 'multiple_choice', NULL, '["A. Carbon monoxide","B. Oxygen","C. Nitrogen","D. Calcium carbonate"]', 'A', 'Carbon monoxide, formed from the burning coke, is the reducing agent: Fe₂O₃ + 3CO → 2Fe + 3CO₂. (Oxygen would oxidise, not reduce; nitrogen is inert here; calcium carbonate removes sandy impurities as slag but does not reduce the ore.) Therefore the correct answer is A: Carbon monoxide.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_cambridge');
